#!/bin/bash
# Guardian Recovery candidate 2026.10.20.7. Default: automatic apply; --dry-run simulates. Never downloads code at runtime.
set -eu
umask 077
[ "$(id -u)" = 0 ] || { echo 'root required' >&2; exit 2; }
command -v python3 >/dev/null || { echo 'Python 3.7+ required' >&2; exit 2; }
DEST=$(mktemp -d /root/mkauth-guardian-update.XXXXXXXX)
python3 - "$DEST" <<'GUARDIAN_PAYLOAD'
import base64,gzip,hashlib,io,sys,tarfile,os
from pathlib import Path
if sys.version_info < (3,7):raise SystemExit('Python 3.7+ required')
payload=base64.b64decode('')
if hashlib.sha256(payload).hexdigest()!='2345e69741deeab24ed4dfb92db34e21722d4bd088c236f960a81a88e2b0ade1':raise SystemExit('Embedded payload hash mismatch')
root=Path(sys.argv[1]);os.chmod(str(root),0o700)
with tarfile.open(fileobj=io.BytesIO(gzip.decompress(payload)),mode='r:') as archive:
    for member in archive:
        if not member.isfile() or '/' in member.name or member.name in ('.','..'):raise SystemExit('Unsafe embedded member')
        target=root/member.name
        with target.open('xb') as stream:stream.write(archive.extractfile(member).read())
        os.chmod(str(target),0o600)
for line in (root/'SHA256SUMS').read_text().splitlines():
    expected,name=line.split('  ',1)
    if hashlib.sha256((root/name).read_bytes()).hexdigest()!=expected:raise SystemExit('File checksum mismatch')
print('Verified package extracted to '+str(root),flush=True)
GUARDIAN_PAYLOAD
(cd "$DEST" && python3 -m unittest -v test_recovery test_backup_supervisor test_compatible_backup test_install_frontend test_installer_settings test_install_sources test_radius_signals test_notification_messages)
exec python3 "$DEST/install_frontend.py" "$@"
